import{_ as p,D as e,o,c as d,m as a,a as n,G as r,S as h}from"./chunks/framework.DuIEtbrD.js";const k=JSON.parse('{"title":"Typescript用Go重写！效率提升10倍+🚀！开发者要了解的技术趋势","description":"微软宣布将TypeScript编译器及工具链迁移至Go语言,性能提升10倍+","frontmatter":{"title":"Typescript用Go重写！效率提升10倍+🚀！开发者要了解的技术趋势","description":"微软宣布将TypeScript编译器及工具链迁移至Go语言,性能提升10倍+","keywords":"Typescript,TS,Go,Rust,ESbuild,SWC,RSPack,开发效率,编译性能","logo":"https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/icon-ts.png"},"headers":[],"relativePath":"article/2025/typescript-go.md","filePath":"article/2025/typescript-go.md","lastUpdated":1776945570000}'),g={name:"article/2025/typescript-go.md"};function c(y,t,x,f,b,u){const l=e("Obsolete"),i=e("Reward"),s=e("Gitalk");return o(),d("div",null,[t[0]||(t[0]=a("h1",{id:"typescript用go重写-效率提升10倍-🚀-开发者要了解的技术趋势",tabindex:"-1"},[n("Typescript用Go重写！效率提升10倍+🚀！开发者要了解的技术趋势 "),a("a",{class:"header-anchor",href:"#typescript用go重写-效率提升10倍-🚀-开发者要了解的技术趋势","aria-label":'Permalink to "Typescript用Go重写！效率提升10倍+🚀！开发者要了解的技术趋势"'},"​")],-1)),r(l,{date:"2025-03-28"}),t[1]||(t[1]=h('<p>2025年3月，微软宣布将TypeScript编译器及工具链迁移至Go语言，这一决策在开发者社区引发强烈震动。以TypeScript之父Anders Hejlsberg领衔的团队，通过Go语言重构实现了编译速度提升10倍、内存占用减少50%的突破性成果。这不仅标志着微软在编程语言生态上的重大战略调整，更揭示了现代软件开发中性能优化与工程实践的深层逻辑</p><h2 id="a-10x-faster-typescript" tabindex="-1">A 10x Faster TypeScript <a class="header-anchor" href="#a-10x-faster-typescript" aria-label="Permalink to &quot;A 10x Faster TypeScript&quot;">​</a></h2><p>事情是这样的，前几天在Typescript官网查了一个配置信息，就顺便看了下官方的博客文章信息，意外发现这篇文章<a href="https://devblogs.microsoft.com/typescript/typescript-native-port/" target="_blank" rel="noreferrer">A 10x Faster TypeScript</a></p><p>文章大概是描述了微软在TypeScript编译器及工具链使用go进行部分重构测试后，展示了编译速度提升10倍、内存占用减少50%的突破性成果</p><p>文章还提到了做出此举的背后原因，并在重构前对技术语言选型进行了调研，最终选择了go。除此之外我还看了下<a href="https://www.youtube.com/watch?v=10qowKUW82U" target="_blank" rel="noreferrer">YouTube</a> 上的采访，并将核心内容记录在文中了，下面来看具体内容</p><h2 id="性能对比" tabindex="-1">性能对比 <a class="header-anchor" href="#性能对比" aria-label="Permalink to &quot;性能对比&quot;">​</a></h2><p>Typescript Go原生实现已经能够加载许多流行的TypeScript项目，包括TypeScript编译器本身。并对比tsc测试了一些流行库，下面是性能对比</p><table><thead><tr><th>代码库</th><th style="text-align:right;">代码量</th><th style="text-align:right;">Current(tsx)</th><th style="text-align:right;">Native(Go)</th><th style="text-align:right;">速度提升</th></tr></thead><tbody><tr><td><a href="https://github.com/microsoft/vscode" target="_blank" rel="noreferrer">VS Code</a></td><td style="text-align:right;">150万行</td><td style="text-align:right;">77.8s</td><td style="text-align:right;">7.5s</td><td style="text-align:right;">10.4x</td></tr><tr><td><a href="https://github.com/microsoft/playwright" target="_blank" rel="noreferrer">Playwright</a></td><td style="text-align:right;">35万行</td><td style="text-align:right;">11.1s</td><td style="text-align:right;">1.1s</td><td style="text-align:right;">10.1x</td></tr><tr><td><a href="https://github.com/typeorm/typeorm" target="_blank" rel="noreferrer">TypeORM</a></td><td style="text-align:right;">27万行</td><td style="text-align:right;">17.5s</td><td style="text-align:right;">1.3s</td><td style="text-align:right;">13.5x</td></tr><tr><td><a href="https://github.com/date-fns/date-fns" target="_blank" rel="noreferrer">date-fns</a></td><td style="text-align:right;">10万行</td><td style="text-align:right;">6.5s</td><td style="text-align:right;">0.7s</td><td style="text-align:right;">9.5x</td></tr><tr><td><a href="https://github.com/trpc/trpc" target="_blank" rel="noreferrer">tRPC</a> (server + client)</td><td style="text-align:right;">1.8万行</td><td style="text-align:right;">5.5s</td><td style="text-align:right;">0.6s</td><td style="text-align:right;">9.1x</td></tr><tr><td><a href="https://github.com/ReactiveX/rxjs" target="_blank" rel="noreferrer">rxjs</a> (observable)</td><td style="text-align:right;">0.2万行</td><td style="text-align:right;">1.1s</td><td style="text-align:right;">0.1s</td><td style="text-align:right;">11.0x</td></tr></tbody></table><p>官方这样解释到：<u>采用原生本身就提升3.x倍，然后并发也会提升3.x倍，再加上其他一些性能总体接近10倍！除此之外内存可以降低50%左右</u></p><h2 id="为什么要重构" tabindex="-1">为什么要重构 <a class="header-anchor" href="#为什么要重构" aria-label="Permalink to &quot;为什么要重构&quot;">​</a></h2><p>首先要知道ts的编译器是ts本身实现的，这其中逃脱不了JS的魔爪，Javascript本身就不使用高密集计算，这在编译处理AST等相关大型复杂逻辑上会显得吃力。尤其是在代码量上来后，加载速度、类型提示速度会明显下降，不知道各位在工作中有没有遇到过，编辑器打开都会转半天</p><p>同时这也是社区开发者最关心的问题，因此官方也宣布将TypeScript编译器及工具链迁移至Go语言</p><h2 id="typescript规划进展" tabindex="-1">Typescript规划进展 <a class="header-anchor" href="#typescript规划进展" aria-label="Permalink to &quot;Typescript规划进展&quot;">​</a></h2><p>官方以Corsa 作为项目代号进行go重构，整个项目都放在 <a href="https://github.com/microsoft/typescript-go" target="_blank" rel="noreferrer">typescript-go新仓库</a> 中</p><p>目前Typescript的最新版本为5.8.2，官方宣布老版本会持续更新到6.x，并会在6.x版本中进行提示一些后续警告信息，以告诉开发者后续的go版本中可能有稍微的兼容性等等</p><p>go版本会在<code>7.x</code>版本中发布，目前基于go的Typescript编译器(类似于tsc)快完成了，并计划2025年春末或夏初推出预览版，2025年末将会完成重构的所有工作，可能还会发布重构后的版本</p><h2 id="为什么是go" tabindex="-1">为什么是Go <a class="header-anchor" href="#为什么是go" aria-label="Permalink to &quot;为什么是Go&quot;">​</a></h2><p>为什么是Go而不是Rust❓❓</p><p>我们知道Typescript的发布到现在已经有很多代码库了，体量已经是非常大了，如果使用其他语言重构可能就会产生兼容性问题，如果选择的不合理会造成很多错误，这无疑是一种灾难</p><p>最可靠的方案是迁移现有代码库。而现有代码库有一些基本假设，其中之一就是 依赖自动垃圾回收。这个前提基本上就排除了 Rust，因为 Rust 没有自动 GC</p><p>在 Rust 中，你可以使用手动内存管理、引用计数等方式，但 Rust 对数据结构的所有权管理非常严格，尤其是禁止循环数据结构。而我们现有的代码库中，循环数据结构无处不在，比如：</p><ul><li>AST既有子节点指向父节点，也有父节点指向子节点</li><li>类型系统 也是高度递归的，存在大量循环引用</li><li>等等...</li></ul><p>而相比Go学习曲线显然比 Rust 低得多，基本大部分开发者2周就可以上手，并且它们的代码结构其实很相似，这也是 Go 的一个巨大优势</p><table><thead><tr><th style="text-align:left;">评估维度</th><th style="text-align:left;">Go优势</th><th style="text-align:left;">Rust/C#短板</th></tr></thead><tbody><tr><td style="text-align:left;">内存管理</td><td style="text-align:left;">自动GC避免手动内存管理，适配TypeScript编译器复杂对象图</td><td style="text-align:left;">Rust无GC需处理生命周期，C#托管堆开销大</td></tr><tr><td style="text-align:left;">代码迁移</td><td style="text-align:left;">结构语法与TypeScript相似度达70%，支持逐文件移植</td><td style="text-align:left;">Rust所有权模型导致架构颠覆性改变</td></tr><tr><td style="text-align:left;">并发模型</td><td style="text-align:left;">Goroutine轻量级并发处理数万AST节点遍历</td><td style="text-align:left;">async/await模式引入额外复杂度</td></tr><tr><td style="text-align:left;">工具链成熟度</td><td style="text-align:left;">编译速度&lt;1秒，标准库覆盖网络/文本处理等编译器基础需求</td><td style="text-align:left;">C#跨平台工具链调试体验待优化</td></tr><tr><td style="text-align:left;">生态兼容性</td><td style="text-align:left;">通过cgo轻松集成JavaScript引擎，支持渐进式迁移</td><td style="text-align:left;">Rust与JS互操作需复杂FFI封装</td></tr></tbody></table><h2 id="工具链技术趋势" tabindex="-1">工具链技术趋势 <a class="header-anchor" href="#工具链技术趋势" aria-label="Permalink to &quot;工具链技术趋势&quot;">​</a></h2><p>放眼当下很多原来由JS写的编译器或者其他打包工具等工具链，在体量上来后或现代开发诉求后都慢慢转向了原生</p><p>在本届(19)的D2终端技术大会上，尤雨溪也介绍了当前前端的一些痛点现状、以及如何根治这些问题</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-03-28_10.58.11.png" alt=""></p><p>我们知道vite由于开发环境和生成环境的不一致可能会导致一定的兼容性问题，核心问题还是开发环境使用esbuild进预打包，生产环境使用rollup进行打包造成的差异</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-03-29_10.49.14.png" alt=""></p><p>并且esbuild使用go开发的开发环境体验会很好，但生产环境打包使用rollup还是基于JS开发的，效率会明显下降很多</p><p>前端开发的工具链太多太多，从：gulp、webpack、vite、eslint、prettier等等，碎片化太严重，当然不得不说前端技术发展很迅速，但对于开发者来说完全掌握他们的成本也成了陡峭曲线上升的趋势。所以尤雨溪提出了统一工具链的想法，比如提议的：Rust写的<a href="https://oxc.rs/" target="_blank" rel="noreferrer">Oxc</a>工具链、弥补Vite不足的<a href="https://rolldown.rs/" target="_blank" rel="noreferrer">Rolldown</a>等等</p><p>除此之外还有很多转原生的工具，如：</p><ul><li><a href="https://esbuild.github.io/" target="_blank" rel="noreferrer">基于Go的esbuild</a></li><li><a href="https://www.rspack.dev/" target="_blank" rel="noreferrer">考虑webpack性能不足后，基于Rust开发的Rspack</a></li><li><a href="https://swc.rs/" target="_blank" rel="noreferrer">基于Rust的swc对比Babel编译提升不少</a></li><li><a href="https://webassembly.org/" target="_blank" rel="noreferrer">密集任务性能好、安全可靠的WebAssembly，也都推荐使用Rust、Go进行编译开发</a></li></ul><h2 id="展望未来" tabindex="-1">展望未来 <a class="header-anchor" href="#展望未来" aria-label="Permalink to &quot;展望未来&quot;">​</a></h2><p>虽然JavaScript以其灵活性可以快速实现很多功能，但在性能方面相较于原生语言还是略显逊色。作为开发者推荐学习<a href="https://www.rust-lang.org/" target="_blank" rel="noreferrer">Rust</a>、<a href="https://go.dev/" target="_blank" rel="noreferrer">Go</a>，学习他们不会很难也不会花很长时间</p>',36)),r(i),r(s)])}const _=p(g,[["render",c]]);export{k as __pageData,_ as default};
